package com.neo.tracepilot;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.*;
final class TraceView extends View{
 private List<TraceDb.Point> pts=new ArrayList<>();private List<TraceDb.Gap> gaps=new ArrayList<>();private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG),grid=new Paint(Paint.ANTI_ALIAS_FLAG);
 TraceView(Context c){super(c);grid.setColor(Color.rgb(24,34,47));grid.setStrokeWidth(1);setMinimumHeight(Ui.dp(c,280));}
 void data(List<TraceDb.Point> a,List<TraceDb.Gap> g){pts=new ArrayList<>(a);gaps=new ArrayList<>(g);invalidate();}
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Ui.SURFACE);int w=getWidth(),h=getHeight();for(int i=1;i<6;i++){float x=w*i/6f,y=h*i/6f;c.drawLine(x,0,x,h,grid);c.drawLine(0,y,w,y,grid);}if(pts.size()<2)return;double minLa=1e9,maxLa=-1e9,minLo=1e9,maxLo=-1e9;for(TraceDb.Point q:pts){minLa=Math.min(minLa,q.lat);maxLa=Math.max(maxLa,q.lat);minLo=Math.min(minLo,q.lon);maxLo=Math.max(maxLo,q.lon);}double dla=Math.max(1e-6,maxLa-minLa),dlo=Math.max(1e-6,maxLo-minLo);float pad=Ui.dp(getContext(),18);for(int i=1;i<pts.size();i++){TraceDb.Point a=pts.get(i-1),b=pts.get(i);p.setColor(Ui.modeColor(b.mode));p.setStrokeWidth(Ui.dp(getContext(),3));p.setPathEffect(null);p.setStrokeCap(Paint.Cap.ROUND);float x1=pad+(float)((a.lon-minLo)/dlo)*(w-2*pad),y1=h-pad-(float)((a.lat-minLa)/dla)*(h-2*pad),x2=pad+(float)((b.lon-minLo)/dlo)*(w-2*pad),y2=h-pad-(float)((b.lat-minLa)/dla)*(h-2*pad);c.drawLine(x1,y1,x2,y2,p);}for(TraceDb.Gap g:gaps){if(!"reconstructed".equals(g.status))continue;p.setColor(Ui.modeColor(g.mode));p.setStrokeWidth(Ui.dp(getContext(),3));p.setPathEffect(new DashPathEffect(new float[]{12,9},0));float x1=pad+(float)((g.startLon-minLo)/dlo)*(w-2*pad),y1=h-pad-(float)((g.startLat-minLa)/dla)*(h-2*pad),x2=pad+(float)((g.endLon-minLo)/dlo)*(w-2*pad),y2=h-pad-(float)((g.endLat-minLa)/dla)*(h-2*pad);c.drawLine(x1,y1,x2,y2,p);}p.setPathEffect(null);}
}
